function distinctDifferenceArray(nums) {
  const n = nums.length;
  const suffixDistinct = new Array(n + 1).fill(0);
  const suffix = new Set();
  for (let i = n - 1; i >= 0; i--) {
    suffix.add(nums[i]);
    suffixDistinct[i] = suffix.size;
  }

  const prefix = new Set();
  const diff = [];
  for (let i = 0; i < n; i++) {
    prefix.add(nums[i]);
    diff.push(prefix.size - suffixDistinct[i + 1]);
  }
  return diff;
}

